1421	/// Atomically write a viewer routing file. Mirrors the sidebar plugin's
1422	/// `write_routing` so both writers produce a byte-identical payload; the
1423	/// viewer reaches this only on the new-todo / new-note promotion path
1424	/// to update its own pane title without going through the plugin.
1425	fn write_routing_to(path: &Path, kind: &str, id: Option<u64>) {
1426	    if let Some(parent) = path.parent() {
1427	        if std::fs::create_dir_all(parent).is_err() {
1428	            return;
1429	        }
1430	    }
1431	    let payload = match id {
1432	        Some(id) => format!("{{\"kind\":\"{kind}\",\"id\":{id}}}"),
1433	        None => format!("{{\"kind\":\"{kind}\"}}"),
1434	    };
1435	    let name = path
1436	        .file_name()
1437	        .and_then(|s| s.to_str())
1438	        .unwrap_or("viewer");
1439	    let tmp = match path.parent() {
1440	        Some(p) => p.join(format!(".{name}.tmp")),
1441	        None => PathBuf::from(format!(".{name}.tmp")),
1442	    };
1443	    if std::fs::write(&tmp, payload).is_ok() {
1444	        let _ = std::fs::rename(&tmp, path);
1445	    }
