386	    /// Single-line textarea field whose recorded inner content rectangle
387	    /// contains the click, plus that rectangle. Returns `None` if the click
388	    /// missed every single-line textarea (Body has its own routing).
389	    fn text_field_at(&self, row: u16, col: u16) -> Option<(Field, Rect)> {
390	        self.text_field_areas.iter().find_map(|(field, rect)| {
391	            if row >= rect.y
392	                && row < rect.y + rect.height
393	                && col >= rect.x
394	                && col < rect.x + rect.width
395	            {
396	                Some((*field, *rect))
397	            } else {
398	                None
399	            }
400	        })
401	    }
402	
403	    /// The text-content rect recorded for `field`, if it has one.
404	    fn text_field_inner(&self, field: Field) -> Option<Rect> {
405	        self.text_field_areas
406	            .iter()
407	            .find(|(f, _)| *f == field)
408	            .map(|(_, r)| *r)
409	    }
