411	    /// Mutable access to the single-line textarea backing `field`, if any.
412	    fn single_line_textarea_mut(
413	        &mut self,
414	        field: Field,
415	    ) -> Option<&mut tui_textarea::TextArea<'static>> {
416	        match field {
417	            Field::Title => Some(&mut self.title),
418	            Field::Tags => Some(&mut self.tags),
419	            _ => None,
420	        }
421	    }
