928	
929	    /// A locally edited field is kept and the message line flags the
930	    /// conflict; the baseline still advances so the next flush only sends
931	    /// the still-pending change.
932	    #[test]
933	    fn refresh_keeps_local_edit_and_flags_conflict() {
934	        let mut form = NoteForm::from_parts(
