157	/// The merged, validated set of agent profiles, keyed by `tool_type`.
158	#[derive(Debug, Clone)]
159	pub struct ProfileSet {
160	    profiles: BTreeMap<String, AgentProfile>,
161	}
162	
163	impl ProfileSet {
164	    /// Load the shipped defaults, merge the user override at
165	    /// `<config-dir>/panopt/agent-types.toml` if it exists, and validate. This
166	    /// is the production entry point; tests use [`ProfileSet::from_layers`] to
167	    /// supply layers directly.
168	    pub fn load() -> Result<Self, ProfileError> {
169	        let override_toml = match Self::override_path() {
170	            Some(path) if path.exists() => {
171	                Some(std::fs::read_to_string(&path).map_err(ProfileError::Io)?)
172	            }
173	            _ => None,
174	        };
175	        Self::from_layers(DEFAULTS_TOML, override_toml.as_deref())
176	    }
177	
178	    /// Merge an explicit default layer with an optional override layer and
179	    /// validate the result. Pure: no filesystem access, so the merge and
180	    /// validation rules are unit-testable without seeding a config dir.
181	    pub fn from_layers(
182	        default_toml: &str,
183	        override_toml: Option<&str>,
184	    ) -> Result<Self, ProfileError> {
185	        let mut table: toml::Table =
186	            toml::from_str(default_toml).map_err(|source| ProfileError::Parse {
187	                layer: "default",
188	                source,
189	            })?;
190	        if let Some(over) = override_toml {
191	            let over: toml::Table = toml::from_str(over).map_err(|source| ProfileError::Parse {
192	                layer: "override",
