fn handle_mouse(&mut self, mouse: Mouse) -> bool {
    match mouse {
        Mouse::LeftClick(line, _col) => {
            if line < 0 {
                return false;
            }
            let idx = self.scroll + line as usize;
            if idx >= self.items.len() {
