            self.activate_item(idx, false);
            if let Some(plugin) = self.plugin_pane {
                focus_pane_with_id(plugin, false, false);
            }
            true
        }
        Mouse::ScrollUp(_) => {
            if self.move_cursor(-1) {
                self.preview_cursor();
            }
            true
        }
        Mouse::ScrollDown(_) => {
            if self.move_cursor(1) {
                self.preview_cursor();
            }
            true
        }
        _ => false,
    }
}

