240	/// Add `column` to `table` only if it is not already there. Used by migrations
241	/// that may collide with a transitional dev-database state where the column
242	/// landed before its `user_version` bump did. `decl` is the type+constraint
243	/// text after the column name, exactly as it would appear in an `ALTER TABLE`.
244	///
245	/// `column` and `table` are fixed in-crate identifiers, not caller input, so
246	/// interpolating them into the SQL is safe.
247	fn add_column_if_missing(
248	    conn: &Connection,
249	    table: &str,
250	    column: &str,
251	    decl: &str,
252	) -> Result<(), rusqlite::Error> {
253	    let mut stmt = conn.prepare(&format!("PRAGMA table_info({table})"))?;
254	    let mut rows = stmt.query([])?;
255	    while let Some(row) = rows.next()? {
256	        let existing: String = row.get(1)?;
257	        if existing == column {
258	            return Ok(());
259	        }
260	    }
261	    drop(rows);
262	    drop(stmt);
263	    conn.execute_batch(&format!("ALTER TABLE {table} ADD COLUMN {column} {decl};"))
264	}
