266	/// Bring `conn` up to [`SCHEMA_VERSION`], creating tables on a fresh database.
267	///
268	/// Idempotent: a database already at the current version is left untouched.
269	/// Each step is gated on the stored `user_version`, so a v1 database upgrades
270	/// in place and a fresh one runs every step in order to the same end state.
271	pub(crate) fn migrate(conn: &Connection) -> Result<(), rusqlite::Error> {
272	    let version: i64 = conn.pragma_query_value(None, "user_version", |r| r.get(0))?;
273	    if version < 1 {
274	        conn.execute_batch(SCHEMA_V1)?;
275	    }
276	    if version < 2 {
277	        conn.execute_batch(SCHEMA_V2)?;
278	    }
279	    if version < 3 {
280	        conn.execute_batch(SCHEMA_V3)?;
281	    }
282	    if version < 4 {
283	        apply_v4(conn)?;
284	    }
285	    if version < 5 {
286	        apply_v5(conn)?;
287	    }
288	    if version < 6 {
289	        apply_v6(conn)?;
290	    }
291	    if version < 7 {
292	        apply_v7(conn)?;
293	    }
294	    if version < 8 {
295	        apply_v8(conn)?;
296	    }
297	    if version < 9 {
298	        apply_v9(conn)?;
299	    }
300	    if version < 10 {
301	        apply_v10(conn)?;
302	    }
303	    if version < 11 {
304	        apply_v11(conn)?;
305	    }
306	    if version < 12 {
307	        apply_v12(conn)?;
308	    }
309	    if version < 13 {
310	        apply_v13(conn)?;
311	    }
312	    if version != SCHEMA_VERSION {
313	        conn.pragma_update(None, "user_version", SCHEMA_VERSION)?;
314	    }
315	    Ok(())
316	}
