318	/// Version 7: soft delete (todo #54).
319	///
320	/// Each item-bearing table grows a nullable `deleted_at` column. `*_delete`
321	/// stamps it with `datetime('now')` instead of issuing a `DELETE FROM`, and
322	/// every read path (`*_list`, `*_get`, `fetch_*`, the blocker-resolution helper)
323	/// filters on `deleted_at IS NULL`. The row stays behind so a future undelete
324	/// surface has something to revive; recovery / cleanup tooling is deferred.
325	fn apply_v7(conn: &Connection) -> Result<(), rusqlite::Error> {
326	    add_column_if_missing(conn, "todos", "deleted_at", "TEXT")?;
327	    add_column_if_missing(conn, "scratchpads", "deleted_at", "TEXT")?;
328	    add_column_if_missing(conn, "agent_tools", "deleted_at", "TEXT")?;
329	    add_column_if_missing(conn, "processes", "deleted_at", "TEXT")?;
330	    Ok(())
