81	/// The activity states the status interpreter derives from agent output. Used
82	/// here only as the key type for a profile's status patterns; the matching
83	/// semantics (precedence, idle fallthrough) belong to the interpreter (#138).
84	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Deserialize)]
85	#[serde(rename_all = "lowercase")]
86	pub enum AgentState {
87	    Thinking,
88	    Idle,
89	    Waiting,
90	    Done,
91	}
92	
93	impl AgentState {
94	    /// The lowercase wire name, matching the `serde(rename_all = "lowercase")`
95	    /// above. Used to project the status patterns to `.panopt/agent-types.md`
96	    /// (todo #142), where the sidebar's wasm-side `AgentState` reads them back -
97	    /// the two enums share these strings as their contract.
98	    pub fn as_str(self) -> &'static str {
99	        match self {
100	            AgentState::Thinking => "thinking",
101	            AgentState::Idle => "idle",
102	            AgentState::Waiting => "waiting",
103	            AgentState::Done => "done",
104	        }
105	    }
106	}
