108	/// The launch template for an agent type. Rendered by the spawn interpreter
109	/// into a concrete process launch; this struct only holds the un-rendered
110	/// templates.
111	#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
112	#[serde(deny_unknown_fields)]
113	pub struct SpawnSpec {
114	    /// The argument vector, each element a template. `argv[0]` is the program.
115	    pub argv: Vec<String>,
116	    /// Environment variables to set on the child, values templated. Keys are
117	    /// literal.
118	    #[serde(default)]
119	    pub env: BTreeMap<String, String>,
120	    /// Files to materialize before spawn: name -> templated contents. Each is
121	    /// written to a temp file whose path replaces `{{file:NAME}}` in `argv`
122	    /// and `env`.
123	    #[serde(default)]
124	    pub files: BTreeMap<String, String>,
125	}
126	
127	/// The status rules for an agent type: each activity state maps to an ordered
128	/// list of regex patterns matched against the agent's output. A
129	/// [`std::collections::BTreeMap`] newtype so the public type is stable while
130	/// the interpreter (#138) grows methods on it.
131	#[derive(Debug, Clone, Default, PartialEq, Eq, Deserialize)]
132	#[serde(transparent)]
133	pub struct StatusRules(pub BTreeMap<AgentState, Vec<String>>);
134	
135	/// One agent type. The top-level value in `defaults.toml` and the override,
136	/// keyed by its `tool_type` string.
137	#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
138	#[serde(deny_unknown_fields)]
139	pub struct AgentProfile {
140	    /// Human-facing label for spawn UIs.
141	    pub display_name: String,
142	    /// The model a config spawned from this type defaults to, when the agent
143	    /// takes one. `None` leaves it to the agent's own default.
144	    #[serde(default)]
145	    pub default_model: Option<String>,
146	    /// Extra arguments appended after `spawn.argv` by default. Empty unless the
147	    /// type wants standing flags.
148	    #[serde(default)]
149	    pub default_args: Vec<String>,
150	    /// How to launch an instance of this type.
151	    pub spawn: SpawnSpec,
152	    /// How to read an instance's activity from its output.
153	    #[serde(default)]
154	    pub status: StatusRules,
155	}
156	
157	/// The merged, validated set of agent profiles, keyed by `tool_type`.
158	#[derive(Debug, Clone)]
159	pub struct ProfileSet {
160	    profiles: BTreeMap<String, AgentProfile>,
161	}
162	
163	impl ProfileSet {
164	    /// Load the shipped defaults, merge the user override at
165	    /// `<config-dir>/panopt/agent-types.toml` if it exists, and validate. This
166	    /// is the production entry point; tests use [`ProfileSet::from_layers`] to
167	    /// supply layers directly.
168	    pub fn load() -> Result<Self, ProfileError> {
169	        let override_toml = match Self::override_path() {
170	            Some(path) if path.exists() => {
171	                Some(std::fs::read_to_string(&path).map_err(ProfileError::Io)?)
172	            }
173	            _ => None,
174	        };
175	        Self::from_layers(DEFAULTS_TOML, override_toml.as_deref())
176	    }
177	
178	    /// Merge an explicit default layer with an optional override layer and
179	    /// validate the result. Pure: no filesystem access, so the merge and
180	    /// validation rules are unit-testable without seeding a config dir.
181	    pub fn from_layers(
182	        default_toml: &str,
183	        override_toml: Option<&str>,
184	    ) -> Result<Self, ProfileError> {
185	        let mut table: toml::Table =
186	            toml::from_str(default_toml).map_err(|source| ProfileError::Parse {
187	                layer: "default",
188	                source,
189	            })?;
190	        if let Some(over) = override_toml {
191	            let over: toml::Table = toml::from_str(over).map_err(|source| ProfileError::Parse {
192	                layer: "override",
193	                source,
194	            })?;
195	            merge_tables(&mut table, over);
196	        }
197	        let profiles: BTreeMap<String, AgentProfile> = toml::Value::Table(table)
198	            .try_into()
199	            .map_err(|source| ProfileError::Parse {
200	                layer: "merged",
201	                source,
202	            })?;
203	        let set = ProfileSet { profiles };
204	        set.validate()?;
205	        Ok(set)
206	    }
