208	    /// The user override path, `<config-dir>/panopt/agent-types.toml`. `None`
209	    /// only when no per-user config directory exists at all.
210	    fn override_path() -> Option<PathBuf> {
211	        dirs::config_dir().map(|d| d.join("panopt").join("agent-types.toml"))
212	    }
213	
214	    /// The profile for a `tool_type`, or `None` if no type carries that key.
215	    pub fn get(&self, tool_type: &str) -> Option<&AgentProfile> {
216	        self.profiles.get(tool_type)
217	    }
