219	    /// Whether a `tool_type` is a known profile. The check #139 uses to
220	    /// validate an `agent_tools.tool_type` before accepting it.
221	    pub fn contains(&self, tool_type: &str) -> bool {
222	        self.profiles.contains_key(tool_type)
223	    }
224	
225	    /// The known `tool_type` keys, sorted.
226	    pub fn keys(&self) -> impl Iterator<Item = &str> {
227	        self.profiles.keys().map(String::as_str)
228	    }
229	
230	    /// `(tool_type, profile)` pairs, sorted by key.
231	    pub fn iter(&self) -> impl Iterator<Item = (&str, &AgentProfile)> {
232	        self.profiles.iter().map(|(k, v)| (k.as_str(), v))
233	    }
234	
235	    /// Number of known types.
236	    pub fn len(&self) -> usize {
237	        self.profiles.len()
238	    }
239	
240	    /// Whether no types are defined. Always false for a normally-loaded set
241	    /// (the shipped defaults are never empty), but kept for completeness.
242	    pub fn is_empty(&self) -> bool {
243	        self.profiles.is_empty()
244	    }
