246	    /// Reject any spawn template that references an unknown placeholder. Run
247	    /// once at load so a typo fails fast rather than at spawn time.
248	    fn validate(&self) -> Result<(), ProfileError> {
249	        for (tool_type, profile) in &self.profiles {
250	            let files: BTreeSet<&str> = profile.spawn.files.keys().map(String::as_str).collect();
251	            let check = |template: &str| -> Result<(), ProfileError> {
252	                for placeholder in placeholders(template) {
253	                    let known = match placeholder.strip_prefix("file:") {
254	                        Some(name) => files.contains(name),
255	                        None => KNOWN_PLACEHOLDERS.contains(&placeholder),
256	                    };
257	                    if !known {
258	                        return Err(ProfileError::UnknownPlaceholder {
259	                            tool_type: tool_type.clone(),
260	                            placeholder: placeholder.to_string(),
261	                        });
262	                    }
263	                }
264	                Ok(())
265	            };
266	            for arg in &profile.spawn.argv {
267	                check(arg)?;
268	            }
269	            for value in profile.spawn.env.values() {
270	                check(value)?;
271	            }
272	            for contents in profile.spawn.files.values() {
273	                check(contents)?;
274	            }
275	        }
276	        Ok(())
277	    }
278	}
