280	/// Recursively merge `over` into `base`. Tables merge key-by-key; every other
281	/// value (scalar or array) in `over` replaces the one in `base`. This is the
282	/// whole merge policy: maps merge, lists and scalars replace.
283	fn merge_tables(base: &mut toml::Table, over: toml::Table) {
284	    for (key, over_value) in over {
285	        match (base.get_mut(&key), over_value) {
286	            (Some(toml::Value::Table(base_table)), toml::Value::Table(over_table)) => {
287	                merge_tables(base_table, over_table);
288	            }
289	            (_, over_value) => {
290	                base.insert(key, over_value);
291	            }
292	        }
293	    }
294	}
