296	/// The `{{...}}` placeholder names in a template, trimmed, in order. An
297	/// unterminated `{{` ends the scan. Slices borrow from `template`.
298	fn placeholders(template: &str) -> Vec<&str> {
299	    let mut out = Vec::new();
300	    let mut rest = template;
301	    while let Some(open) = rest.find("{{") {
302	        let after = &rest[open + 2..];
303	        let Some(close) = after.find("}}") else {
304	            break;
305	        };
306	        out.push(after[..close].trim());
307	        rest = &after[close + 2..];
308	    }
309	    out
310	}
