91	/// caller owns and cleans up.
92	pub fn build_launch(
93	    profile: &AgentProfile,
94	    facts: &Facts,
95	    dir: &Path,
96	) -> Result<Launch, RenderError> {
97	    // Pass 1: render each file's contents (facts only) and write it, recording
98	    // name -> path so pass 2 can resolve `{{file:NAME}}`.
99	    let mut file_paths: BTreeMap<String, PathBuf> = BTreeMap::new();
