134	    name: &str,
135	    facts: &Facts,
136	    file_paths: &BTreeMap<String, PathBuf>,
137	) -> Result<String, RenderError> {
138	    match name.strip_prefix("file:") {
139	        Some(file) => file_paths
140	            .get(file)
141	            .map(|p| p.to_string_lossy().into_owned())
142	            .ok_or_else(|| RenderError::UnknownFile(file.to_string())),
143	        None => facts
144	            .lookup(name)
