149	/// Substitute every `{{name}}` in `template` using `resolve`. An unterminated
150	/// `{{` is an error (the load validator's scanner stops at it silently; here we
151	/// are producing output, so a dangling open brace must not be emitted raw).
152	fn substitute(
153	    template: &str,
154	    resolve: &dyn Fn(&str) -> Result<String, RenderError>,
155	) -> Result<String, RenderError> {
156	    let mut out = String::with_capacity(template.len());
157	    let mut rest = template;
158	    while let Some(open) = rest.find("{{") {
159	        out.push_str(&rest[..open]);
160	        let after = &rest[open + 2..];
161	        let close = after.find("}}").ok_or(RenderError::Unterminated)?;
162	        out.push_str(&resolve(after[..close].trim())?);
163	        rest = &after[close + 2..];
164	    }
165	    out.push_str(rest);
166	    Ok(out)
