pub struct Handler {
    state: Arc<Mutex<Store>>,
    /// Built once in `new()` from [`build_router`] and consulted by this
    /// type's manual `ServerHandler` impl (see `call_tool`, `list_tools`).
    tool_router: ToolRouter<Self>,
}

/// Wire shape for a note in `note_list` output.
#[derive(Serialize)]
struct NoteDto {
    id: u64,
    title: String,
}

/// Wire shape for `note_get`: title, body, tags, and timestamps.
#[derive(Serialize)]
struct NoteDetailDto {
    id: u64,
    title: String,
    body: String,
    tags: Vec<String>,
    created_at: String,
    updated_at: String,
}

impl NoteDetailDto {
    fn from_note(pad: &Note) -> Self {
        NoteDetailDto {
            id: pad.id,
            title: pad.title.clone(),
            body: pad.body.clone(),
            tags: pad.tags.clone(),
            created_at: pad.created_at.clone(),
            updated_at: pad.updated_at.clone(),
        }
    }
}

/// Wire shape for `id_kind`: the resource kind and a short human label
/// (title for todos/notes, `display_name` falling back to `name` for
/// agent tools and processes - the same fallback the cockpit's projection
/// uses).
#[derive(Serialize)]
struct IdKindDto {
    kind: &'static str,
    label: String,
}

/// Wire shape for one project in `project_list` output: a project's identity,
/// projection path, and the live badges the cross-project switcher renders.
/// Mirrors [`panopt_core::ProjectSummary`] one-to-one; `last_activity` is
/// `null` when the project has no todos or notes.
#[derive(Serialize)]
struct ProjectSummaryDto {
    identity: String,
    root: String,
    name: String,
    agents_active: usize,
    todos_open: usize,
    todos_in_progress: usize,
    locks_held: usize,
    last_activity: Option<String>,
}

impl From<ProjectSummary> for ProjectSummaryDto {
    fn from(p: ProjectSummary) -> Self {
        ProjectSummaryDto {
            identity: p.identity,
            root: p.root,
            name: p.name,
            agents_active: p.agents_active,
            todos_open: p.todos_open,
            todos_in_progress: p.todos_in_progress,
            locks_held: p.locks_held,
            last_activity: p.last_activity,

