/// Bring `conn` up to [`SCHEMA_VERSION`], creating tables on a fresh database.
///
/// Idempotent: a database already at the current version is left untouched.
/// Each step is gated on the stored `user_version`, so a v1 database upgrades
/// in place and a fresh one runs every step in order to the same end state.
pub(crate) fn migrate(conn: &Connection) -> Result<(), rusqlite::Error> {
    let version: i64 = conn.pragma_query_value(None, "user_version", |r| r.get(0))?;
    if version < 1 {
        conn.execute_batch(SCHEMA_V1)?;
    }
    if version < 2 {
        conn.execute_batch(SCHEMA_V2)?;
    }
    if version < 3 {
        conn.execute_batch(SCHEMA_V3)?;
    }
    if version < 4 {
        apply_v4(conn)?;
    }
    if version < 5 {
        apply_v5(conn)?;
    }
    if version < 6 {
        apply_v6(conn)?;
    }
    if version < 7 {
        apply_v7(conn)?;
    }
    if version < 8 {
        apply_v8(conn)?;
    }
    if version < 9 {
        apply_v9(conn)?;
    }
    if version < 10 {
        apply_v10(conn)?;
    }
    if version < 11 {
        apply_v11(conn)?;
    }
    if version < 12 {
        apply_v12(conn)?;
    }
    if version < 13 {
        apply_v13(conn)?;
    }
    if version < 14 {
        apply_v14(conn)?;
    }
    if version != SCHEMA_VERSION {
        conn.pragma_update(None, "user_version", SCHEMA_VERSION)?;
    }
    Ok(())
}

/// Version 7: soft delete (todo #54).
///
/// Each item-bearing table grows a nullable `deleted_at` column. `*_delete`
/// stamps it with `datetime('now')` instead of issuing a `DELETE FROM`, and
/// every read path (`*_list`, `*_get`, `fetch_*`, the blocker-resolution helper)

/// Version 13: `state_since` on processes (bug #163).
///
/// A Unix-epoch-seconds stamp of when a process's `agent_state` last changed,
/// written by `process_report` on a state transition. The processes projection
/// renders `idle:<age>` as `now - state_since` while the agent is in the `idle`
/// state - a real "how long has it been sitting idle" age, replacing the old
/// `idle:` that was sourced from registry presence (time since last MCP call),
/// which measured connection heartbeat, not idleness. Integer epoch rather than
/// the `datetime('now')` TEXT the other timestamps use, so the projection can
/// diff it against the render clock without parsing.
fn apply_v13(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(conn, "processes", "state_since", "INTEGER")
}

/// Version 14: `system_prompt` on agent_tools (todo #140).
///
/// A per-config system prompt the cockpit's agent-config form edits and a
/// spawn-spec template can land into a launch flag or file. Stored on the
/// durable config (the slot), not the instance, so it persists across runs.
/// `NOT NULL DEFAULT ''` keeps every existing row valid with an empty prompt.
fn apply_v14(conn: &Connection) -> Result<(), rusqlite::Error> {
    add_column_if_missing(
        conn,
        "agent_tools",
        "system_prompt",
        "TEXT NOT NULL DEFAULT ''",
    )
}

/// True if a table named `table` exists. Used by migrations that must stay
/// idempotent against a transitional dev-database that already applied a
/// rename or create before its `user_version` bump landed.
fn table_exists(conn: &Connection, table: &str) -> Result<bool, rusqlite::Error> {
    let count: i64 = conn.query_row(
        "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?1",
        [table],
        |r| r.get(0),
    )?;
    Ok(count > 0)
}

