#[test]
fn fresh_database_has_the_v14_agent_tools_system_prompt() {
    // A row inserted without naming system_prompt picks up the NOT NULL
    // DEFAULT '' the V14 ALTER established, so every pre-V14 config reads
    // back as an empty prompt rather than NULL.
    let conn = Connection::open_in_memory().unwrap();
    migrate(&conn).unwrap();
    conn.execute_batch(
        "INSERT INTO projects (id, root) VALUES (1, '/x');
         INSERT INTO agent_tools (project_id, id, name, tool_type, created_at)
             VALUES (1, 1, 'Claude', 'claude-code', '');",
    )
    .unwrap();
    let prompt: String = conn
        .query_row(
            "SELECT system_prompt FROM agent_tools WHERE id = 1",
            [],
            |r| r.get(0),
        )
        .unwrap();
    assert_eq!(prompt, "");
}

#[test]
fn fresh_database_has_v4_note_timestamps() {
    let conn = Connection::open_in_memory().unwrap();
    migrate(&conn).unwrap();
    // The v4 columns exist and accept inserts that set both timestamps.
    // A fresh database is fully migrated, so the table is `notes` (V9).
    conn.execute_batch(
        "INSERT INTO projects (id, root) VALUES (1, '/x');
         INSERT INTO notes (project_id, id, title, body, created_at, updated_at)
             VALUES (1, 1, 't', '', datetime('now'), datetime('now'));",
    )
    .unwrap();
    let updated: String = conn
        .query_row("SELECT updated_at FROM notes WHERE id = 1", [], |r| {
            r.get(0)
        })
        .unwrap();
    assert!(!updated.is_empty(), "fresh note has updated_at set");
}

