92	/// Atomically replace `target` with `contents`.
93	///
94	/// The temp file is created in `target`'s own directory, which guarantees it is
95	/// on the same filesystem - a precondition for `rename` to be atomic.
96	fn atomic_write(target: &Path, contents: &str) -> io::Result<()> {
97	    let parent = target.parent().ok_or_else(|| {
98	        io::Error::new(
99	            io::ErrorKind::InvalidInput,
100	            "target has no parent directory",
101	        )
102	    })?;
103	    let file_name = target
104	        .file_name()
105	        .and_then(|n| n.to_str())
106	        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "target has no file name"))?;
107	
108	    let seq = TMP_SEQ.fetch_add(1, Ordering::Relaxed);
109	    let tmp = parent.join(format!(".{file_name}.tmp.{}.{seq}", std::process::id()));
110	
111	    match fs::write(&tmp, contents).and_then(|()| fs::rename(&tmp, target)) {
112	        Ok(()) => Ok(()),
113	        Err(e) => {
114	            // Best-effort cleanup so a failed write leaves no `.tmp` litter.
115	            let _ = fs::remove_file(&tmp);
116	            Err(e)
117	        }
118	    }
119	}
