121	/// Render the todo index: a GitHub-style checklist, one line per todo, each
122	/// linking to that todo's own file.
123	pub(crate) fn render_todos_index_md(todos: &[Todo]) -> String {
124	    let mut out = String::from("# Todos\n\n");
125	    if todos.is_empty() {
126	        out.push_str("_(no todos)_\n");
127	        return out;
128	    }
129	    for todo in todos {
130	        let mark = match todo.status {
131	            TodoStatus::Completed => 'x',
132	            // Closed-but-not-done renders as `[-]`, a common markdown
133	            // convention for cancelled / won't-do items. It distinguishes
134	            // these from still-open todos without claiming they're done.
135	            TodoStatus::NotDone => '-',
136	            _ => ' ',
137	        };
138	        out.push_str(&format!(
139	            "- [{mark}] [#{id}](todos/{id}.md) {title} - {status}, {priority}, updated {updated}\n",
140	            id = todo.id,
141	            title = todo.title,
142	            status = todo.status.as_str(),
143	            priority = todo.priority.as_str(),
144	            updated = todo.updated_at,
145	        ));
146	    }
147	    out
148	}
149	
150	/// Render one todo as a self-contained markdown file: a `---` frontmatter block
151	/// of structured fields, the title as an H1, the body, then any comments.
152	pub(crate) fn render_todo_md(todo: &Todo) -> String {
153	    let blockers = todo
154	        .blockers
155	        .iter()
156	        .map(|b| b.to_string())
157	        .collect::<Vec<_>>()
158	        .join(", ");
159	
160	    let mut out = String::from("---\n");
161	    out.push_str(&format!("status: {}\n", todo.status.as_str()));
162	    out.push_str(&format!("priority: {}\n", todo.priority.as_str()));
163	    out.push_str(&format!("assignee: {}\n", todo.assignee));
164	    out.push_str(&format!("tags: {}\n", todo.tags.join(", ")));
165	    out.push_str(&format!("blockers: {blockers}\n"));
166	    out.push_str(&format!("created: {}\n", todo.created_at));
167	    out.push_str(&format!("updated: {}\n", todo.updated_at));
168	    if let Some(completed) = &todo.completed_at {
169	        out.push_str(&format!("completed: {completed}\n"));
170	    }
171	    out.push_str("---\n\n");
172	
173	    out.push_str(&format!("# {}\n", todo.title));
174	
175	    if !todo.body.trim().is_empty() {
176	        out.push('\n');
177	        out.push_str(todo.body.trim_end());
178	        out.push('\n');
179	    }
180	
181	    if !todo.comments.is_empty() {
182	        out.push_str("\n## Comments\n");
183	        for comment in &todo.comments {
184	            out.push_str(&format!(
185	                "\n**{}** - {}\n\n",
186	                comment.author, comment.created_at
187	            ));
188	            out.push_str(comment.body.trim_end());
189	            out.push('\n');
190	        }
191	    }
192	    out
193	}
194	
195	/// Render a note as a `---` frontmatter block of tags + timestamps, the
196	/// title as an H1, then its body verbatim. The frontmatter mirrors
197	/// `render_todo_md` so every per-item file in the projection carries the same
198	/// structured-then-prose shape. Empty `tags` renders as `tags: ` (no special
199	/// case), exactly like todos do.
200	pub(crate) fn render_note_md(pad: &Note) -> String {
201	    let mut out = String::from("---\n");
202	    out.push_str(&format!("tags: {}\n", pad.tags.join(", ")));
203	    out.push_str(&format!("created: {}\n", pad.created_at));
204	    out.push_str(&format!("updated: {}\n", pad.updated_at));
205	    out.push_str("---\n\n");
206	    out.push_str(&format!("# {}\n\n", pad.title));
207	    out.push_str(&pad.body);
208	    if !pad.body.is_empty() && !pad.body.ends_with('\n') {
209	        out.push('\n');
210	    }
211	    out
212	}
