             id           INTEGER PRIMARY KEY AUTOINCREMENT,
             project_id   INTEGER NOT NULL REFERENCES projects(id),
             process_id   INTEGER NOT NULL,
             content      TEXT    NOT NULL,
             created_at   TEXT    NOT NULL,
             delivered_at TEXT
         );",
    )
}

